package com.opencrm.order.operations;
import com.opencrm.order.domain.OrderProblem;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.flywaydb.core.Flyway;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
@Tag("integration") @Testcontainers
class OperationsIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 JdbcTemplate db;
 @BeforeAll static void migrate(){Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas("order_management").defaultSchema("order_management").load().migrate();}
 @BeforeEach void setup(){db=spy(new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl()+"&currentSchema=order_management",postgres.getUsername(),postgres.getPassword())));db.execute("TRUNCATE snapshot_inbox,outbox_events CASCADE");}
 String order(String scope){String id=UUID.randomUUID().toString();db.update("INSERT INTO snapshot_inbox(snapshot_id,scope_id,customer_id,quote_id,accepted_revision,payload,payload_hash,received_at) VALUES(?,?,'customer',?,1,'{}',?,CURRENT_TIMESTAMP)",id,scope,id,"a".repeat(64));db.update("INSERT INTO orders(id,order_number,scope_id,customer_id,quote_id,quote_number,accepted_revision,snapshot_id,snapshot_json,snapshot_hash,status,created_at,updated_at,created_by,updated_by) VALUES(?,?,?,'customer',?,'Q',1,?,'{}',?,'IN_PROGRESS',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,'operator','operator')",id,id,scope,id,id,"a".repeat(64));return id;}
 void outbox(String id,boolean exhausted){db.update("INSERT INTO outbox_events(uuid,aggregate_type,aggregate_id,event_type,payload,created_at,exhausted_at) VALUES(?,'Order',?,'oms.test','{}',clock_timestamp()-interval '120 seconds',CASE WHEN ? THEN clock_timestamp() ELSE NULL END)",UUID.randomUUID().toString(),id,exhausted);}
 @Test void byteLimitUsesUtf8AndLeavesStoredRecordsUntouched(){String id=order("pilot");var admission=new IntakeAdmission(db,"pilot",4,2);admission.checkPayload("éé");assertEquals(422,assertThrows(OrderProblem.class,()->admission.checkPayload("ééé")).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM snapshot_inbox",Integer.class));}
 @Test void backlogIsScopedRetryableAndNeverDropsAcceptedReceipts(){String local=order("pilot"),other=order("other");outbox(other,true);outbox(other,true);var admission=new IntakeAdmission(db,"pilot",1024,2);admission.checkNewIntake();outbox(local,false);admission.checkNewIntake();outbox(local,true);assertEquals(503,assertThrows(IntakeAdmission.Saturated.class,admission::checkNewIntake).status());assertEquals(4,db.queryForObject("SELECT count(*) FROM outbox_events",Integer.class));assertEquals(2,db.queryForObject("SELECT count(*) FROM snapshot_inbox",Integer.class));db.update("UPDATE outbox_events SET published=true WHERE aggregate_id=?",local);admission.checkNewIntake();}
 @Test void cachedScopedGaugesMeasureBacklogAndScrapesNeverQuery(){String local=order("pilot"),other=order("other");outbox(local,false);outbox(local,true);outbox(other,true);var registry=new SimpleMeterRegistry();var metrics=new OperationalMetrics(db,registry,"pilot",1000,5);metrics.refresh();assertEquals(2,registry.get("oms.outbox.pending").gauge().value());assertEquals(1,registry.get("oms.outbox.exhausted").gauge().value());assertTrue(registry.get("oms.outbox.oldest.pending.seconds").gauge().value()>=120);clearInvocations(db);for(int i=0;i<20;i++)registry.get("oms.outbox.pending").gauge().value();verifyNoInteractions(db);}
 @Test void scopeMustBeConfiguredForAdmissionAndMetricsNeverReadOtherDeployments(){order("other");var admission=new IntakeAdmission(db,"",1024,2);assertThrows(IntakeAdmission.Saturated.class,admission::checkNewIntake);var registry=new SimpleMeterRegistry();var metrics=new OperationalMetrics(db,registry,"",100,5);clearInvocations(db);metrics.refresh();verifyNoInteractions(db);assertEquals(0,registry.get("oms.operations.configured").gauge().value());}
 void stalledTasks(String order){String line=UUID.randomUUID().toString();db.update("INSERT INTO order_lines(id,order_id,source_line_id,description,ordered) VALUES(?,?,'line','Item',1)",line,order);for(int i=0;i<2;i++){String task=UUID.randomUUID().toString();db.update("INSERT INTO order_tasks(id,order_id,line_id,kind,template_version,status) VALUES(?,?,?,?,1,?)",task,order,line,i==0?"FINANCE_ACK":"ALLOCATION",i==0?"UNKNOWN":"WAITING_EXTERNAL");if(i==0)db.update("INSERT INTO order_exceptions(id,order_id,task_id,category,severity,next_action,reason) VALUES(?,?,?,'FINANCE_UNKNOWN','HIGH','RECONCILE','provider timeout')",UUID.randomUUID().toString(),order,task);else db.update("INSERT INTO task_operations(operation_key,task_id,order_id,body_hash,status,deadline_at) VALUES(?,?,?,?,'WAITING_EXTERNAL',clock_timestamp()-interval '60 seconds')",UUID.randomUUID().toString(),task,order,"a".repeat(64));}}
 @Test void unknownOverdueAndFinanceCountsAreScopedAndScanLimitIsExplicit(){String local=order("pilot"),other=order("other");stalledTasks(local);stalledTasks(other);for(int i=0;i<3;i++)outbox(local,false);var registry=new SimpleMeterRegistry();var metrics=new OperationalMetrics(db,registry,"pilot",1,5);metrics.refresh();assertEquals(1,registry.get("oms.outbox.pending").gauge().value());assertEquals(1,registry.get("oms.operations.scan.limit").gauge().value());assertEquals(1,registry.get("oms.tasks.unknown").gauge().value());assertEquals(1,registry.get("oms.tasks.overdue").gauge().value());assertEquals(1,registry.get("oms.finance.exceptions.open").gauge().value());}
 @Test void failedRefreshPreservesLastSampleAndMakesFailureVisible(){String local=order("pilot");outbox(local,false);var registry=new SimpleMeterRegistry();var metrics=new OperationalMetrics(db,registry,"pilot",100,5);metrics.refresh();db.execute("ALTER TABLE outbox_events RENAME TO temporarily_unavailable_outbox");try{assertDoesNotThrow(metrics::refresh);assertEquals(1,registry.get("oms.outbox.pending").gauge().value());assertEquals(1,registry.get("oms.operations.refresh.failures").gauge().value());assertFalse(Double.isNaN(registry.get("oms.operations.sample.age.seconds").gauge().value()));}finally{db.execute("ALTER TABLE temporarily_unavailable_outbox RENAME TO outbox_events");}}
 @Test void oversizedLineCollectionNeverEntersDurableInbox(){var ds=new DriverManagerDataSource(postgres.getJdbcUrl()+"&currentSchema=order_management",postgres.getUsername(),postgres.getPassword());var mapper=tools.jackson.databind.json.JsonMapper.builder().build();var service=new com.opencrm.order.service.OrderService(db,new org.springframework.jdbc.datasource.DataSourceTransactionManager(ds),mapper,mock(com.opencrm.order.security.OrderAccess.class),true,"pilot");var lines=new java.util.ArrayList<com.opencrm.common.order.AcceptedOrderSnapshot.Line>();for(int i=0;i<201;i++)lines.add(new com.opencrm.common.order.AcceptedOrderSnapshot.Line("line-"+i,"p","Item","DIGITAL","ONE_TIME",1,"EA","0","0","0","0","ONE_TIME",null,null));var snapshot=new com.opencrm.common.order.AcceptedOrderSnapshot(1,"too-many",UUID.randomUUID().toString(),"Q",1,"pilot","customer",java.time.Instant.now(),"USD","0","0","0","0","address","approval","tax","config",lines);String payload=mapper.writeValueAsString(snapshot);assertThrows(OrderProblem.class,()->service.acceptTrustedSnapshot(payload,com.opencrm.order.service.OrderService.hash(payload)));assertEquals(0,db.queryForObject("SELECT count(*) FROM snapshot_inbox",Integer.class));}
}